// ─── EaseCare HTTP client ───
//
// Ported from ease-care-ui-design/src/app/services/api.ts (the reference client).
// - Base URL from VITE_API_BASE_URL (relative "/api/v1" → same-origin via the LB).
// - Bearer token injected from the "easecare_tokens" JSON blob.
// - On 401: refresh once via POST /auth/refresh, then retry the original request.
// - EC-0086: refresh-OK-but-retry-still-4xx ⇒ permission error, NOT auth failure
//   (don't log the user out — propagate so the caller decides).
// INTEGRATION-owned; never regenerated by Figma Make.

/** API base URL — VITE_API_BASE_URL (trailing slashes stripped), defaults to /api/v1. */
export const API_BASE =
  import.meta.env.VITE_API_BASE_URL?.replace(/\/+$/, "") || "/api/v1";

const TOKENS_KEY = "easecare_tokens";

export interface TokenBundle {
  accessToken: string;
  refreshToken: string;
  /** seconds until access token expiry (from backend `expires_in`) */
  expiresIn?: number;
  /** ISO timestamp when the bundle was stored */
  storedAt?: string;
}

/** Persist tokens (called by AuthContext after firebase-login / refresh). */
export function setTokens(bundle: Omit<TokenBundle, "storedAt">): void {
  localStorage.setItem(
    TOKENS_KEY,
    JSON.stringify({ ...bundle, storedAt: new Date().toISOString() }),
  );
}

/** Remove tokens (logout / dead session). */
export function clearTokens(): void {
  localStorage.removeItem(TOKENS_KEY);
}

function readTokens(): TokenBundle | null {
  try {
    const raw = localStorage.getItem(TOKENS_KEY);
    return raw ? (JSON.parse(raw) as TokenBundle) : null;
  } catch {
    return null;
  }
}

export function getAccessToken(): string | null {
  return readTokens()?.accessToken ?? null;
}

/** True when a stored session exists (used by AuthContext hydration). */
export function hasSession(): boolean {
  return !!readTokens()?.accessToken;
}

/**
 * Refresh the access token using the stored refresh token.
 * Returns true if new tokens were obtained and stored.
 */
async function tryRefreshToken(): Promise<boolean> {
  try {
    const refreshToken = readTokens()?.refreshToken;
    if (!refreshToken) return false;

    const res = await fetch(`${API_BASE}/auth/refresh`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ refresh_token: refreshToken }),
    });
    if (!res.ok) return false;

    const data = await res.json();
    setTokens({
      accessToken: data.access_token,
      refreshToken: data.refresh_token,
      expiresIn: data.expires_in,
    });
    return true;
  } catch {
    return false;
  }
}

/** Build a querystring from a params object (skips null/undefined/empty). */
export function qs(params: Record<string, unknown>): string {
  const sp = new URLSearchParams();
  for (const [k, v] of Object.entries(params)) {
    if (v === null || v === undefined || v === "") continue;
    if (Array.isArray(v)) {
      for (const item of v) sp.append(k, String(item));
    } else {
      sp.append(k, String(v));
    }
  }
  const s = sp.toString();
  return s ? `?${s}` : "";
}

function dispatchUnauthorized(): void {
  window.dispatchEvent(new CustomEvent("easecare:unauthorized"));
}

/** JSON request with bearer auth + 401 refresh-retry. */
export async function fetchJson<T>(path: string, options?: RequestInit): Promise<T> {
  const url = path.startsWith("http") ? path : `${API_BASE}${path}`;
  const token = getAccessToken();
  const res = await fetch(url, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...options?.headers,
    },
  });

  if (res.ok) {
    if (res.status === 204) return undefined as T;
    return res.json();
  }

  if (res.status === 401) {
    const refreshed = await tryRefreshToken();
    if (refreshed) {
      const newToken = getAccessToken();
      const retryRes = await fetch(url, {
        ...options,
        headers: {
          "Content-Type": "application/json",
          ...(newToken ? { Authorization: `Bearer ${newToken}` } : {}),
          ...options?.headers,
        },
      });
      if (retryRes.ok) {
        if (retryRes.status === 204) return undefined as T;
        return retryRes.json();
      }
      // EC-0086: refresh worked but retry still 4xx ⇒ role/permission issue,
      // not a dead session. Propagate; do NOT log out.
      const retryText = await retryRes.text();
      throw new Error(retryText || `HTTP ${retryRes.status}`);
    }
    dispatchUnauthorized();
    throw new Error("Authentication expired");
  }

  const text = await res.text();
  throw new Error(text || `HTTP ${res.status}`);
}

/** Multipart POST (file uploads). Browser sets Content-Type with boundary. */
export async function fetchMultipart<T>(
  path: string,
  buildFormData: () => FormData,
  method: "POST" | "PUT" = "POST",
): Promise<T> {
  const url = path.startsWith("http") ? path : `${API_BASE}${path}`;
  const token = getAccessToken();
  const res = await fetch(url, {
    method,
    headers: token ? { Authorization: `Bearer ${token}` } : {},
    body: buildFormData(),
  });
  if (res.ok) return res.json();

  if (res.status === 401) {
    const refreshed = await tryRefreshToken();
    if (refreshed) {
      const newToken = getAccessToken();
      const retryRes = await fetch(url, {
        method,
        headers: newToken ? { Authorization: `Bearer ${newToken}` } : {},
        body: buildFormData(), // fresh FormData for retry
      });
      if (retryRes.ok) return retryRes.json();
      const retryText = await retryRes.text();
      throw new Error(retryText || `HTTP ${retryRes.status}`);
    }
    dispatchUnauthorized();
    throw new Error("Authentication expired");
  }

  const text = await res.text();
  throw new Error(text || `HTTP ${res.status}`);
}

/** POST /auth/refresh proactively (e.g. before expiry). Safe no-op if no session. */
export async function refreshNow(): Promise<boolean> {
  return tryRefreshToken();
}
